function* naturals() { for (let i = 1; ; i++) yield i; }

const firstSquares = naturals()
  .filter(n => n % 3 === 0)
  .map(n => n * n)
  .take(4)
  .toArray();          // [9, 36, 81, 144]; the generator stops here

const sum = naturals().take(100).reduce((a, b) => a + b, 0);

function* activeEmails(people) {
  for (const p of people) if (p.active) yield p.email;
}
function* trimmed(source) {
  for (const s of source) yield s.trim().toLowerCase();
}

const first3 = [];
for (const e of trimmed(activeEmails(people))) {
  first3.push(e);
  if (first3.length === 3) break;   // closes the upstream generators
}
